using System.Globalization;
using System.Security.Cryptography;
using System.Text;

namespace Crecisol.Domain.Tenancy;

/// <summary>
/// Opaque idempotency operation key generated by a trusted backoffice workflow.
/// Knowing a key is NEVER authorization, proof of tenant ownership or permission.
/// </summary>
public sealed record TenantProvisioningOperationId
{
    private TenantProvisioningOperationId(Guid value) => Value = value;
    public Guid Value { get; }

    public static TenantProvisioningOperationId From(Guid value) =>
        value != Guid.Empty ? new TenantProvisioningOperationId(value)
            : throw new InvalidOperationException("Provisioning operation ID is required.");

    public override string ToString() => "TenantProvisioningOperationId[redacted]";
}

/// <summary>
/// Internal global business identity; NOT a slug, domain, hostname or legal name.
/// Globally unique reservations must be enforced in protected storage, not here.
/// </summary>
public sealed record TenantProvisioningBusinessKey
{
    private TenantProvisioningBusinessKey(string value) => Value = value;
    public string Value { get; }

    public static TenantProvisioningBusinessKey FromTrustedCatalog(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw) || raw.Length is < 3 or > 64 ||
            !string.Equals(raw, raw.Trim(), StringComparison.Ordinal) ||
            raw[0] is < 'a' or > 'z' ||
            raw[^1] is not (>= 'a' and <= 'z' or >= '0' and <= '9') ||
            !raw.All(c => c is >= 'a' and <= 'z' or >= '0' and <= '9' or '-'))
            throw new InvalidOperationException("Invalid internal provisioning business key.");
        return new TenantProvisioningBusinessKey(raw);
    }

    public override string ToString() => "TenantProvisioningBusinessKey[redacted]";
}

public enum TenantProvisioningPlanState
{
    Approved = 1,
    Suspended = 2,
    Revoked = 3
}

/// <summary>
/// APPROVED internal backoffice plan, not an API model. Caller must validate
/// real authorization, approval workflow, 4-eyes policy and non-revocation
/// before a future production adapter persists this snapshot. C04-07 has NO
/// authentication, payment, contract activation or production tenant creation.
/// </summary>
public sealed record TrustedTenantProvisioningPlanSnapshot
{
    private TrustedTenantProvisioningPlanSnapshot(
        TenantProvisioningOperationId operationId,
        TenantId tenantId,
        TenantActorId sponsoringActorId,
        TenantProvisioningBusinessKey businessKey,
        TenantAddressMode addressMode,
        TenantProvisioningPlanState state,
        long approvalRevision,
        DateTimeOffset approvedAtUtc,
        DateTimeOffset expiresAtUtc)
    {
        OperationId = operationId;
        TenantId = tenantId;
        SponsoringActorId = sponsoringActorId;
        BusinessKey = businessKey;
        AddressMode = addressMode;
        State = state;
        ApprovalRevision = approvalRevision;
        ApprovedAtUtc = approvedAtUtc;
        ExpiresAtUtc = expiresAtUtc;
        IntentFingerprint = ComputeFingerprint(
            operationId, tenantId, sponsoringActorId, businessKey,
            addressMode, approvalRevision);
    }

    public TenantProvisioningOperationId OperationId { get; }
    public TenantId TenantId { get; }
    public TenantActorId SponsoringActorId { get; }
    public TenantProvisioningBusinessKey BusinessKey { get; }
    public TenantAddressMode AddressMode { get; }
    public TenantProvisioningPlanState State { get; }
    public long ApprovalRevision { get; }
    public DateTimeOffset ApprovedAtUtc { get; }
    public DateTimeOffset ExpiresAtUtc { get; }
    public string IntentFingerprint { get; }

    public static TrustedTenantProvisioningPlanSnapshot RestoreFromTrustedBackoffice(
        TenantProvisioningOperationId operationId,
        TenantId tenantId,
        TenantActorId sponsoringActorId,
        TenantProvisioningBusinessKey businessKey,
        TenantAddressMode addressMode,
        TenantProvisioningPlanState state,
        long approvalRevision,
        DateTimeOffset approvedAtUtc,
        DateTimeOffset expiresAtUtc)
    {
        ArgumentNullException.ThrowIfNull(operationId);
        ArgumentNullException.ThrowIfNull(tenantId);
        ArgumentNullException.ThrowIfNull(sponsoringActorId);
        ArgumentNullException.ThrowIfNull(businessKey);
        if (!Enum.IsDefined(addressMode) || !Enum.IsDefined(state) ||
            approvalRevision <= 0)
            throw new InvalidOperationException("Invalid trusted provisioning plan revision/state.");
        RequireUtc(approvedAtUtc);
        RequireUtc(expiresAtUtc);
        if (approvedAtUtc >= expiresAtUtc)
            throw new InvalidOperationException("Invalid approval validity window.");

        return new TrustedTenantProvisioningPlanSnapshot(
            operationId, tenantId, sponsoringActorId, businessKey, addressMode,
            state, approvalRevision, approvedAtUtc, expiresAtUtc);
    }

    public bool IsApprovedAtUtc(DateTimeOffset nowUtc)
    {
        RequireUtc(nowUtc);
        return State == TenantProvisioningPlanState.Approved &&
            ApprovedAtUtc <= nowUtc && nowUtc < ExpiresAtUtc;
    }

    private static string ComputeFingerprint(
        TenantProvisioningOperationId operationId, TenantId tenantId,
        TenantActorId actorId, TenantProvisioningBusinessKey businessKey,
        TenantAddressMode mode, long revision)
    {
        // Stable canonical UTF-8/ASCII sequence with explicit schema version.
        // The fingerprint detects changes; it is NOT an authentication MAC.
        var canonical = "crecisol.c04-07.v1|" +
            operationId.Value.ToString("N") + "|" +
            tenantId.Value.ToString("N") + "|" +
            actorId.Value.ToString("N") + "|" +
            businessKey.Value + "|" +
            ((int)mode).ToString(CultureInfo.InvariantCulture) + "|" +
            revision.ToString(CultureInfo.InvariantCulture);
        return Convert.ToHexString(SHA256.HashData(
            Encoding.ASCII.GetBytes(canonical))).ToLowerInvariant();
    }

    internal static void RequireUtc(DateTimeOffset value)
    {
        if (value == default || value.Offset != TimeSpan.Zero)
            throw new InvalidOperationException("Provisioning timestamps must be UTC.");
    }

    public override string ToString() => "TrustedTenantProvisioningPlanSnapshot[redacted]";
}

/// <summary>
/// Immutable receipt returned by a FUTURE atomic protected store. A receipt
/// CANNOT grant access or publish an Active tenant. The future adapter must
/// commit a single tenant and operation row in ONE InnoDB transaction.
/// </summary>
public sealed record TrustedTenantProvisioningReceipt
{
    private TrustedTenantProvisioningReceipt(
        TenantProvisioningOperationId operationId, TenantId tenantId,
        TenantActorId sponsoringActorId, TenantProvisioningBusinessKey businessKey,
        TenantAddressMode addressMode, string fingerprint,
        TenantLifecycleState tenantLifecycle, long storeRevision,
        DateTimeOffset committedAtUtc)
    {
        OperationId = operationId;
        TenantId = tenantId;
        SponsoringActorId = sponsoringActorId;
        BusinessKey = businessKey;
        AddressMode = addressMode;
        IntentFingerprint = fingerprint;
        TenantLifecycle = tenantLifecycle;
        StoreRevision = storeRevision;
        CommittedAtUtc = committedAtUtc;
    }

    public TenantProvisioningOperationId OperationId { get; }
    public TenantId TenantId { get; }
    public TenantActorId SponsoringActorId { get; }
    public TenantProvisioningBusinessKey BusinessKey { get; }
    public TenantAddressMode AddressMode { get; }
    public string IntentFingerprint { get; }
    public TenantLifecycleState TenantLifecycle { get; }
    public long StoreRevision { get; }
    public DateTimeOffset CommittedAtUtc { get; }

    public static TrustedTenantProvisioningReceipt RestoreFromTrustedAtomicStore(
        TenantProvisioningOperationId operationId, TenantId tenantId,
        TenantActorId sponsoringActorId, TenantProvisioningBusinessKey businessKey,
        TenantAddressMode addressMode, string fingerprint,
        TenantLifecycleState tenantLifecycle, long storeRevision,
        DateTimeOffset committedAtUtc)
    {
        ArgumentNullException.ThrowIfNull(operationId);
        ArgumentNullException.ThrowIfNull(tenantId);
        ArgumentNullException.ThrowIfNull(sponsoringActorId);
        ArgumentNullException.ThrowIfNull(businessKey);
        if (!Enum.IsDefined(addressMode) ||
            tenantLifecycle != TenantLifecycleState.Draft || storeRevision <= 0 ||
            fingerprint is null || fingerprint.Length != 64 ||
            !fingerprint.All(c => c is >= '0' and <= '9' or >= 'a' and <= 'f'))
            throw new InvalidOperationException("Invalid/unsafe atomic store receipt.");
        TrustedTenantProvisioningPlanSnapshot.RequireUtc(committedAtUtc);
        return new TrustedTenantProvisioningReceipt(
            operationId, tenantId, sponsoringActorId, businessKey, addressMode,
            fingerprint, tenantLifecycle, storeRevision, committedAtUtc);
    }

    public override string ToString() => "TrustedTenantProvisioningReceipt[redacted]";
}

/// <summary>
/// Synthetic/internal result only. Even a CREATED result never grants
/// membership, a verified host, an Active tenant, a DSN or private access.
/// </summary>
public sealed record TenantProvisioningResult
{
    private TenantProvisioningResult(
        TenantId tenantId, TenantProvisioningOperationId operationId,
        bool newlyCreated, long storeRevision)
    {
        TenantId = tenantId;
        OperationId = operationId;
        NewlyCreated = newlyCreated;
        StoreRevision = storeRevision;
    }

    public TenantId TenantId { get; }
    public TenantProvisioningOperationId OperationId { get; }
    public bool NewlyCreated { get; }
    public long StoreRevision { get; }

    public static TenantProvisioningResult FromAtomicStore(
        TrustedTenantProvisioningPlanSnapshot plan,
        TrustedTenantProvisioningReceipt receipt, bool newlyCreated,
        DateTimeOffset nowUtc)
    {
        ArgumentNullException.ThrowIfNull(plan);
        ArgumentNullException.ThrowIfNull(receipt);
        TrustedTenantProvisioningPlanSnapshot.RequireUtc(nowUtc);

        if (!plan.IsApprovedAtUtc(nowUtc) ||
            receipt.OperationId != plan.OperationId ||
            receipt.TenantId != plan.TenantId ||
            receipt.SponsoringActorId != plan.SponsoringActorId ||
            receipt.BusinessKey != plan.BusinessKey ||
            receipt.AddressMode != plan.AddressMode ||
            !string.Equals(receipt.IntentFingerprint, plan.IntentFingerprint,
                StringComparison.Ordinal) ||
            receipt.TenantLifecycle != TenantLifecycleState.Draft ||
            receipt.CommittedAtUtc < plan.ApprovedAtUtc ||
            receipt.CommittedAtUtc > nowUtc ||
            receipt.StoreRevision <= 0)
            throw new UnauthorizedAccessException(
                "Atomic provisioning receipt does not match the approved plan.");

        return new TenantProvisioningResult(
            plan.TenantId, plan.OperationId, newlyCreated, receipt.StoreRevision);
    }

    public override string ToString() => "TenantProvisioningResult[redacted]";
}
